var radius, dur, angle, dir, origin, t, easeT;
seedRandom(index, true);
radius = 400;
dur = 1.5;
angle = random(0, $bm_mul(2, Math.PI));
dir = $bm_mul([
    Math.cos(angle),
    Math.sin(angle)
], random($bm_mul(radius, 0.5), radius));
origin = [
    $bm_div(thisComp.width, 2),
    $bm_div(thisComp.height, 2)
];
t = $bm_sub(time, inPoint);
easeT = easeOut(t, 0, dur, 0, 1);
$bm_rt = $bm_sum(origin, $bm_mul(dir, easeT));

